index 0000000..0000000 100644
--- a/workspace/sandbox/skills/building-accessible-ui/simple-contact-form--framework-vanilla-js--style-dark--validation-message-present/google/gemini-3-flash-preview__s2/script.js
+++ b/workspace/sandbox/skills/building-accessible-ui/simple-contact-form--framework-vanilla-js--style-dark--validation-message-present/google/gemini-3-flash-preview__s2/script.js
@@ -1,86 +1,86 @@
 document.addEventListener('DOMContentLoaded', () => {
     const form = document.getElementById('contact-form');
     const fields = {
         fullName: {
             input: document.getElementById('full-name'),
             error: document.getElementById('full-name-error'),
             validate: (val) => val.trim().length > 0 ? '' : 'Full name is required.'
         },
         email: {
             input: document.getElementById('email'),
             error: document.getElementById('email-error'),
             validate: (val) => {
                 if (!val.trim()) return 'Email address is required.';
                 const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                 return emailRegex.test(val) ? '' : 'Please enter a valid email address.';
             }
         },
         phone: {
             input: document.getElementById('phone'),
             error: document.getElementById('phone-error'),
             validate: (val) => {
                 if (!val) return ''; // Optional
                 const phoneRegex = /^[0-9]{3}-[0-9]{3}-[0-9]{4}$/;
                 return phoneRegex.test(val) ? '' : 'Please follow the format 123-456-7890.';
             }
         }
     };

     const validateField = (fieldKey) => {
         const field = fields[fieldKey];
         const errorMessage = field.validate(field.input.value);
         field.error.textContent = errorMessage;

         if (errorMessage) {
             field.input.setAttribute('aria-invalid', 'true');
             field.input.setAttribute('aria-errormessage', field.error.id);
         } else {
             field.input.removeAttribute('aria-invalid');
             field.input.removeAttribute('aria-errormessage');
         }
         return !errorMessage;
     };

     // Real-time validation
     Object.keys(fields).forEach(key => {
         fields[key].input.addEventListener('input', () => {
             validateField(key);
         });
         fields[key].input.addEventListener('blur', () => {
             validateField(key);
         });
     });

     form.addEventListener('submit', (e) => {
         e.preventDefault();

         let isValid = true;
         Object.keys(fields).forEach(key => {
             if (!validateField(key)) {
                 isValid = false;
             }
         });

         const statusDisplay = document.getElementById('form-status');
         if (isValid) {
             statusDisplay.textContent = 'Message sent successfully!';
             statusDisplay.className = 'success';
             form.reset();
             // Clear error messages after reset
             Object.keys(fields).forEach(key => {
                 fields[key].error.textContent = '';
                 fields[key].input.removeAttribute('aria-invalid');
             });
         } else {
             statusDisplay.textContent = 'Please fix the errors above.';
             statusDisplay.className = 'error-message';

             // Focus first error field
             const firstError = Object.keys(fields).find(key => fields[key].validate(fields[key].input.value));
             if (firstError) {
                 fields[firstError].input.focus();
             }
         }
     });
 });

