    font-size: 0.8rem;
    color: #aaa;
    margin-top: 0.25rem;
}

.error-message {
    color: var(--error-color);
    font-size: 0.85rem;
    margin-top: 0.25rem;
    min-height: 1.2em;
}

button {
    background-color: var(--button-bg);
    color: #000;
    border: none;
    padding: 0.75rem;
    border-radius: 4px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    width: 100%;
    transition: background-color 0.2s;
}

button:hover {
    background-color: var(--button-hover);
}

#form-status {
    margin-top: 1rem;
    text-align: center;
    font-weight: 500;
}

.success {
    color: var(--success-color);
}
